<?php
namespace qqworld_collector\module\translate; class ZhConversion { public function convert($string, $lib) { $patterns = array_keys($lib); $replacements = $lib; $string = str_replace($patterns, $replacements, $string); return $string; } function translate($string, $type = 'zh-hans') { if (!class_exists('\MediaWiki\Languages\Data\ZhConversion')) require __DIR__ . DIRECTORY_SEPARATOR . 'ZhConversion.php'; $patterns = preg_split('/(src|href|srcset)="[^"]*?"/', $string); if (!empty($patterns)) { $replacements = array(); foreach ($patterns as $pattern) { $replacement = $pattern; switch ($type) { case 'zh-cn': case 'zh-sg': $replacement = $this->convert($replacement, \MediaWiki\Languages\Data\ZhConversion::$zh2CN); break; case 'zh-tw': $replacement = $this->convert($replacement, \MediaWiki\Languages\Data\ZhConversion::$zh2TW); break; case 'zh-hk': $replacement = $this->convert($replacement, \MediaWiki\Languages\Data\ZhConversion::$zh2HK); break; } switch ($type) { case 'zh-cn': case 'zh-sg': case 'zh-hans': $replacement = $this->convert($replacement, \MediaWiki\Languages\Data\ZhConversion::$zh2Hans); break; case 'zh-tw': case 'zh-hk': case 'zh-hant': $replacement = $this->convert($replacement, \MediaWiki\Languages\Data\ZhConversion::$zh2Hant); break; } $replacements[] = $replacement; } $string = str_replace($patterns, $replacements, $string); } return $string; } } ?>